fn tconstruct_anvil_material_recipe(input: &Input<'_>, recipe: &Recipe) -> std::ops::ControlFlow<Option<Option<ItemStack>>> {
    use horizon_world::nbt::Tag;
    use std::ops::ControlFlow::{Break, Continue};
    let Recipe::Shaped { width, height, cells, result } = recipe else { return Continue(()); };
    let output = result.create();
    // The source recipe uses forge:difference: a workbench other than the
    // crafting station itself. The shared shaped matcher handles its tag;
    // retain the subtraction before accepting its result.
    if &*output.item == "tconstruct:crafting_station" && *width == 1 && *height == 2
        && cells.first().and_then(Option::as_ref).is_some_and(|ingredient| ingredient.items.len() == 1 && ingredient.items.contains("tconstruct:pattern"))
        && cells.get(1).and_then(Option::as_ref).is_some_and(|ingredient| ingredient.items.contains("tconstruct:crafting_station")) {
        if input.stacks().into_iter().any(|stack| &*stack.item == "tconstruct:crafting_station") { return Break(None); }
        return Continue(());
    }
    if !matches!(&*output.item, "tconstruct:tinkers_anvil" | "tconstruct:scorched_anvil") { return Continue(()); }
    let expected = output.data().and_then(|data| data.other("minecraft:custom_data"))
        .and_then(|data| data.get("tconstruct:anvil")).and_then(|data| data.get("RequiredMaterial"));
    let Some(Tag::String(expected)) = expected else { return Continue(()); };
    let expected = expected.to_string_lossy();
    let fake: Vec<_> = input.stacks().into_iter().filter(|stack| &*stack.item == "tconstruct:fake_storage_block").collect();
    if fake.len() != 3 || fake.iter().any(|stack| {
        !matches!(stack.data().and_then(|data| data.other("minecraft:custom_data")).and_then(|data| data.get("Material")),
            Some(Tag::String(material)) if material.to_string_lossy() == expected)
    }) { return Break(None); }
    Continue(())
}

tconstruct/mixins/tconstruct/survival-me:
fn tconstruct_survival_melter_recipe(input: &Input<'_>, recipe: &Recipe) -> std::ops::ControlFlow<Option<Option<ItemStack>>> {
    use std::ops::ControlFlow::{Break, Continue};
    let Recipe::Shaped { result, .. } = recipe else { return Continue(()); };
    if !matches!(&*result.create().item, "tconstruct:seared_melter" | "tconstruct:seared_fluid_cannon") { return Continue(()); }
    for stack in input.stacks() {
        if matches!(&*stack.item, "tconstruct:seared_fuel_gauge" | "tconstruct:seared_ingot_gauge") {
            let tank = stack.data().and_then(|data| data.other("minecraft:custom_data")).and_then(|data| data.get("tconstruct:tank"));
            if !tconstruct_survival_empty_tank::empty(tank) { return Break(None); }
        }
    }
    Continue(())
}

tconstruct/mixins/tconstruct/source-over:
fn tconstruct_overslime_craft_assemble(input: &Input<'_>, recipe: &Recipe) -> std::ops::ControlFlow<Option<Option<ItemStack>>> {
    let Recipe::Shapeless { result, .. } = recipe else { return std::ops::ControlFlow::Continue(()); };
    if result.item.as_deref() != Some("tconstruct:overslime_bottle_recipe") { return std::ops::ControlFlow::Continue(()); }
    let grid: Vec<Option<ItemStack>> = input.stacks().into_iter().map(|stack| Some(stack.clone())).collect();
    std::ops::ControlFlow::Break(crate::tconstruct_source_overslime_crafting::plan(&grid).map(|(output, _)| Some(output)))
}

fn tconstruct_overslime_craft_remainders(recipe: &str, grid: &[Option<ItemStack>], size: usize) -> std::ops::ControlFlow<Vec<Option<ItemStack>>> {
    if recipe != "tconstruct:overslime_bottle_recipe" { return std::ops::ControlFlow::Continue(()); }
    std::ops::ControlFlow::Break(crate::tconstruct_source_overslime_crafting::plan(grid).map(|(_, rest)| rest).unwrap_or_else(|| vec![None; size * size]))
}

// Source Overslime capacity, refill and damage-shield arithmetic.
// The armor/durability multiplier is the source global durability multiplier.
pub(super) fn capacity(has_overslime: bool, overforced_amount: i32, overforced_trait: i32, overcast: i32, durability_multiplier: f32) -> u32 {
    capacity_with_overlord(has_overslime, overforced_amount, overforced_trait, overcast, durability_multiplier, 0, 0.0, durability_multiplier)
}

pub(super) fn capacity_with_material(has_overslime: bool, overforced_amount: i32, overforced_trait: i32, overcast: i32, durability_multiplier: f32, material: f32) -> u32 {
    capacity_with_material_and_overlord(has_overslime, overforced_amount, overforced_trait, overcast, durability_multiplier, 0, 0.0, durability_multiplier, material)
}

fn capacity_with_overlord(has_overslime: bool, overforced_amount: i32, overforced_trait: i32, overcast: i32, durability_multiplier: f32, overlord: i32, durability: f32, source_multiplier: f32) -> u32 {
    capacity_with_material_and_overlord(has_overslime, overforced_amount, overforced_trait, overcast, durability_multiplier, overlord, durability, source_multiplier, 0.0)
}

fn capacity_with_material_and_overlord(has_overslime: bool, overforced_amount: i32, overforced_trait: i32, overcast: i32, durability_multiplier: f32, overlord: i32, durability: f32, source_multiplier: f32, material: f32) -> u32 {
    let base = if has_overslime { 50.0 } else { 0.0 };
    let effective = overforced_amount.max(0) as f32 / 4.0 + overforced_trait.max(0) as f32;
    let overcast = overcast.max(0) as f32;
    let multiplier = durability_multiplier.max(0.0);
    let copied = if source_multiplier > 0.0 { durability.max(0.0) * 0.1 * overlord.max(0) as f32 / source_multiplier } else { 0.0 };
    ((base + material + 75.0 * effective + 25.0 * overcast + copied) * (1.0 + 0.5 * overcast) * multiplier).clamp(0.0, 32767.0) as u32
}

/// Returns (shield remaining, damage passed to later modifiers).
pub(super) fn absorb(current: u32, loss: u32, cause: Option<&str>) -> (u32, u32) {
    if cause == Some("tconstruct:glowing") { return (current, loss); }
    let absorbed = current.min(loss);
    (current - absorbed, loss - absorbed)
}

/// Source caps the stored shield and consumes only enough matching inputs.
pub(super) fn refill(current: u32, cap: u32, per_item: u32, available: u32, overworked: u32) -> Option<(u32, u32)> {
    if current >= cap || per_item == 0 || available == 0 { return None; }
    let each = per_item.saturating_mul(overworked.saturating_add(1));
    let count = (cap - current).div_ceil(each).min(available);
    Some((current.saturating_add(each.saturating_mul(count)).min(cap), count))
}

/// Pinned source tag tconstruct:overslime_friend.
pub(super) fn friendly(levels: &std::collections::BTreeMap<String, i32>, overforced_amount: i32) -> bool {
    overforced_amount > 0 || ["overgrowth", "overcast", "overburn", "overlord", "overshield", "overwield", "overforced", "overslime_friend", "overworked"]
        .iter().any(|id| levels.get(&format!("tconstruct:{id}")).copied().unwrap_or(0) > 0)
}

